import {createHash} from "node:crypto";
import {readFileSync,writeFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
import assert from 'node:assert/strict';
const root=import.meta.dirname,format=process.argv[2],qualification=process.argv[3]==='--qualify';
assert(['bpi2','bpc1','bpi3'].includes(format));
const current=format==='bpi3';
const config=JSON.parse(readFileSync(root+'/'+(current?'candidate':'baseline')+'.json'));
const {verifyRuntime}=await import(pathToFileURL(config.dependencies));
const verified=verifyRuntime(config.runtime,{lockPath:config.lock});
const world=await import(pathToFileURL(verified.entrypoint));
const kernel=new Uint8Array(readFileSync(verified.kernelPath));
const matrix=JSON.parse(readFileSync(root+'/cases.json'));
const {execute}=await import(pathToFileURL(matrix.oracle));
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
async function invoke(input){
 if(!current)return(await world.admitProcessKernel(kernel,{expectedSha256:verified.kernelSha256})).run(input);
 const instance=await world.Kernel.create({bytes:kernel,expectedSha256:verified.kernelSha256});
 instance.setLimits({input:256<<20,working:256<<20,output:256<<20});
 return world.decodeOutcome(instance.invoke(world.encodeInput(input)));
}
const kind=o=>o.kind.toLowerCase();
async function run(row,image){
 let result=await invoke({image,initialArgs:Uint8Array.from(row.args)}),reply=0,calls=1,peakState=0;const trace=[];
 while(['requested','yielded','progressed'].includes(kind(result))){
  assert(calls<1024,'finite fixture boundary bound');
  peakState=Math.max(peakState,result.state?.length??0);
  let input={image,state:result.state};
  if(kind(result)==='requested'){
   const request=await world.decodeRequest(result.request);
   trace.push({kind:'Requested',identity:request.semanticIdentity,payload:[...request.payload]});
   assert(reply<row.replies.length,'unexpected effect');
   const answer=await world.encodeResult(result.request,Uint8Array.from(row.replies[reply++]));
   input=current?{...input,control:'reply',value:answer}:{...input,result:answer};
  }else if(kind(result)==='yielded'){
   trace.push({kind:'Yielded'});if(current)input.control='resume_yield';
  }
  result=await invoke(input);calls++;
 }
 assert.equal(reply,row.replies.length);
 assert.equal(kind(result),row.expected.kind.toLowerCase());
 assert.deepEqual([...result.value],row.expected.value);
 assert.deepEqual(trace,row.expected.trace);
 if(row.expected.cleanupFailures)assert.deepEqual(result.cleanupFailures.map(x=>[...x]),row.expected.cleanupFailures);
 return{calls,peakState,trace,value:[...result.value],kind:kind(result)};
}
const records=[];
for(const row of matrix.rows){
 const image=new Uint8Array(readFileSync(root+'/'+row.name+'.'+format));
 assert.equal(sha(image),row.images[format].sha256);
 const source=readFileSync(root+'/'+row.name+'.'+(current?'candidate':'baseline')+'.json');
 assert.equal(sha(source),row.sourceSha256[current?'candidate':'baseline']);
 assert.deepEqual(execute(JSON.parse(source),row.args,row.replies),row.expected);
 const samples=[];let result;
 for(let i=0;i<(qualification?1:6);i++){
  const started=process.hrtime.bigint();result=await run(row,image);const ns=Number(process.hrtime.bigint()-started);
  if(!qualification&&i>0)samples.push(ns);
 }
 records.push({name:row.name,imageBytes:image.length,samplesNs:samples,...result});
}
verifyRuntime(config.runtime,{lockPath:config.lock});
console.log(JSON.stringify({format,kernelSha256:verified.kernelSha256,qualification,records}));

